CREATE TABLE academic_team_members(entry_id text NOT NULL REFERENCES portal_entries(id),user_id text NOT NULL REFERENCES "user"(id),role text NOT NULL DEFAULT 'member',joined_at timestamp NOT NULL DEFAULT now(),PRIMARY KEY(entry_id,user_id));
CREATE TABLE academic_team_join_decisions(request_id text PRIMARY KEY REFERENCES portal_requests(id) ON DELETE CASCADE,outcome text NOT NULL CHECK(outcome IN ('accepted','declined')),decided_by text NOT NULL REFERENCES "user"(id),decided_at timestamp NOT NULL DEFAULT now());
INSERT INTO academic_team_members(entry_id,user_id,role) SELECT r.entry_id,r.user_id,'leader' FROM portal_requests r JOIN portal_entries e ON e.id=r.entry_id WHERE r.kind='team_creation' AND r.status IN ('accepted','completed') AND e.published AND NOT e.archived ON CONFLICT DO NOTHING;
INSERT INTO academic_team_members(entry_id,user_id,role) SELECT r.entry_id,r.user_id,'member' FROM portal_requests r JOIN portal_entries e ON e.id=r.entry_id WHERE r.kind='team' AND r.status IN ('accepted','completed') AND e.published AND NOT e.archived ON CONFLICT DO NOTHING;
